"""Pure offline evidence replay: no Native execution, live bridge, or original PE access."""
import hashlib, json, os, pathlib, re, struct, sys
ROOT=pathlib.Path(__file__).resolve().parents[2]
OUT=pathlib.Path(__file__).resolve().parent
opened_paths=[]
def audit_read_guard(event,args):
    if event!='open': return
    path,mode,flags=args
    if not isinstance(path,(str,bytes)): raise RuntimeError('Offline replay forbids opening file descriptors')
    resolved=pathlib.Path(path).resolve()
    if not resolved.is_relative_to(OUT): raise RuntimeError('Offline replay attempted outside evidence directory: '+str(resolved))
    if mode is not None and any(c in mode for c in 'wax+'): raise RuntimeError('Offline replay forbids writes')
    if flags & (os.O_WRONLY|os.O_RDWR|os.O_APPEND|os.O_CREAT|os.O_TRUNC): raise RuntimeError('Offline replay forbids write flags')
    opened_paths.append(resolved.relative_to(OUT).as_posix())
sys.addaudithook(audit_read_guard)
freeze=json.loads((OUT/'freeze_capture_v2.json').read_text(encoding='utf-8'))
def sha(data): return hashlib.sha256(data).hexdigest()
pins=[]
def walk(obj):
    if isinstance(obj,dict):
        if {'path','bytes','sha256'}<=set(obj):
            assert not pathlib.Path(obj['path']).is_absolute(),obj['path']
            data=(ROOT/obj['path']).read_bytes()
            assert len(data)==obj['bytes'] and sha(data)==obj['sha256'],obj['path']
            pins.append(obj['path'])
        for value in obj.values(): walk(value)
    elif isinstance(obj,list):
        for value in obj: walk(value)
walk(freeze)
captures={}
for row in freeze['command_captures_and_specs']:
    if row['file'].endswith('_capture.json'):
        for cmd in json.loads((ROOT/row['pin']['path']).read_text(encoding='utf-8')):
            assert cmd['exit_code']==0
            assert sha(cmd['stdout'].encode())==cmd['stdout_sha256']
            assert sha(cmd['stderr'].encode())==cmd['stderr_sha256']
            captures[cmd['label']]=cmd
windows={w['label']:w for w in freeze['original_PE']['windows']}
raw={k:(ROOT/v['bytes_pin']['path']).read_bytes() for k,v in windows.items()}
pe=freeze['original_PE']
assert 'path' not in pe
image=(ROOT/pe['retained_image_pin']['path']).read_bytes()
assert len(image)==pe['bytes'] and sha(image)==pe['sha256']
peoff=struct.unpack_from('<I',image,0x3c)[0]
assert image[peoff:peoff+4]==b'PE\0\0'
machine,nsections=struct.unpack_from('<HH',image,peoff+4)
optlen=struct.unpack_from('<H',image,peoff+20)[0]
opt=peoff+24
assert machine==pe['machine']==0x14c
assert struct.unpack_from('<H',image,opt)[0]==0x10b
imagebase=struct.unpack_from('<I',image,opt+28)[0]
assert imagebase==int(pe['image_base'],16)
for label,w in windows.items():
    rva=int(w['start_va'],16)-imagebase
    matches=[]
    for i in range(nsections):
        section=opt+optlen+i*40
        _,srva,rawsize,rawoff=struct.unpack_from('<IIII',image,section+8)
        if srva<=rva and rva+w['length']<=srva+rawsize:
            matches.append(rawoff+rva-srva)
    assert matches==[w['file_offset']]
    assert image[w['file_offset']:w['file_offset']+w['length']]==raw[label]
def live_bytes(label):
    rows=[]
    for line in captures[label]['stdout'].splitlines():
        m=re.match(r'^([0-9a-f]{8})  ((?:[0-9a-f]{2} ?)+)  ',line)
        if m: rows.append((int(m[1],16),bytes.fromhex(m[2])))
    assert rows
    for (a,b),(c,d) in zip(rows,rows[1:]): assert a+len(b)==c
    return rows[0][0],b''.join(b for a,b in rows)
for label in ['constructor','commit_head','commit_tail']:
    a,b=live_bytes(label+'_bytes')
    assert a==int(windows[label]['start_va'],16) and b==raw[label]
parts=[live_bytes('copy_helper_bytes_'+str(i)) for i in range(3)]
for (a,b),(c,d) in zip(parts,parts[1:]): assert a+len(b)==c
assert b''.join(b for a,b in parts)==raw['copy_helper']
def at(label,address,length):
    off=address-int(windows[label]['start_va'],16)
    assert off>=0 and off+length<=len(raw[label])
    return raw[label][off:off+length]
checks=[]
def expect(label,address,hexbytes):
    expected=bytes.fromhex(hexbytes)
    assert at(label,address,len(expected))==expected,f'{address:08X}'
    checks.append(f'{address:08X}')
def call(label,address,target):
    b=at(label,address,5)
    assert b[0]==0xe8 and address+5+struct.unpack('<i',b[1:])[0]==target
    checks.append(f'{address:08X}->{target:08X}')
expect('constructor',0x5f6048,'8bf1')
expect('constructor',0x5f6093,'8d8ed8000000')
expect('constructor',0x5f60a3,'8d8e94010000')
call('constructor',0x5f609e,0x8d7710)
call('constructor',0x5f60ae,0x8d7710)
expect('commit_head',0x5f65e2,'8be9')
