expect('commit_head',0x5f6623,'56b98089f800')
call('commit_head',0x5f6629,0x5f52c0)
expect('copy_helper',0x5f52c0,'53568bf1578b7c2410')
expect('copy_helper',0x5f5311,'0fb64f24884e24')
expect('copy_helper',0x5f54e2,'5f8bc65e5bc20400')
def listing(label):
    return {int(m[1],16):' '.join(m[2].split()) for line in captures[label]['stdout'].splitlines()
        if (m:=re.match(r'^([0-9a-f]{8}):\s*(.+)',line))}
comparisons=[]
for saved,live,window in [
 ('saved_constructor_listing','constructor_listing','constructor'),
 ('saved_commit_listing_head','commit_head_listing','commit_head'),
 ('saved_commit_listing_tail','commit_tail_listing','commit_tail')]:
    a,b=listing(saved),listing(live)
    start=int(windows[window]['start_va'],16); end=start+windows[window]['length']
    aa={x:y for x,y in a.items() if start<=x<end}
    bb={x:y for x,y in b.items() if start<=x<end}
    assert aa and aa==bb,(saved,live)
    comparisons.append({'window':window,'matching_instruction_rows':len(aa)})
stores={}
for label in ['copy_helper_head_listing','copy_helper_middle_listing','copy_helper_tail_listing']:
    for addr,insn in listing(label).items():
        m=re.match(r'(MOV (byte|dword) ptr|FSTP (float) ptr) \[ESI \+ (0x[0-9a-f]+)\],?(.*)',insn)
